#include <bits/stdc++.h>
#define FOR_LOOP(i,a,b) for(int i=(a);i<=(b);i++)
#define DEC_LOOP(i,a,b) for(int i=(a);i>=(b);i--)
using namespace std;
const int MAX_SIZE=505;
int n,m,mod;
int mod_add(int a,int b){
	if(a+b>=mod)return a+b-mod;
	return a+b;
}
void add_mod(int &a,int b){
	a=mod_add(a,b);
}
int mod_pow(int base,int exp){
	int res=1;
	while(exp){
		if(exp&1)res=1ll*res*base%mod;
		base=1ll*base*base%mod;
		exp>>=1;
	}
	return res;
}
int factorials[MAX_SIZE*4],inverse_factorials[MAX_SIZE*4];
void precompute(int n){
	factorials[0]=1;
	FOR_LOOP(i,1,n)factorials[i]=1ll*factorials[i-1]*i%mod;
	inverse_factorials[n]=mod_pow(factorials[n],mod-2);
	DEC_LOOP(i,n-1,0)inverse_factorials[i]=1ll*inverse_factorials[i+1]*(i+1)%mod;
}
int choose(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*factorials[n]*inverse_factorials[n-m]%mod*inverse_factorials[m]%mod;
}
vector<int> polyF,gPoly;
int sumOfSeries(int x){
	return x*(x+1)/2;
}
vector<int> multiplyPolynomials(const vector<int> &A,const vector<int> &B){
	vector<int> C(A.size()+B.size()-1);
	FOR_LOOP(i,0,(int)A.size()-1)FOR_LOOP(j,0,(int)B.size()-1)add_mod(C[i+j],1ll*A[i]*B[j]%mod);
	return C;
}
int G(int n,int m){
	return choose(m+n-1,n-1);
}
int main(){
#ifdef pig
	freopen("1439D.in","r",stdin);
	freopen("1439D.out","w",stdout);
#endif
	cin>>m>>n>>mod;
	precompute(m<<1);
	polyF.resize(n+1);gPoly.resize(n+1);
	polyF[0]=1;
	FOR_LOOP(i,1,n){
		FOR_LOOP(j,0,i-1)add_mod(polyF[i],1ll*polyF[j]*polyF[i-1-j]%mod*choose(i-1,j)%mod);
		polyF[i]=1ll*polyF[i]*(i+1)%mod;
	}
	FOR_LOOP(i,1,n){
		FOR_LOOP(j,0,i-1)add_mod(gPoly[i],(2ll*polyF[j]*gPoly[i-1-j]%mod*choose(i-1,j)%mod*(i+1)%mod+1ll*choose(i-1,j)*(sumOfSeries(j)+sumOfSeries(i-1-j))%mod*polyF[j]%mod*polyF[i-1-j]%mod)%mod);
	}
	polyF[0]=0;
	FOR_LOOP(i,0,n)gPoly[i]=1ll*gPoly[i]*inverse_factorials[i]%mod;
	FOR_LOOP(i,0,n)polyF[i]=1ll*polyF[i]*inverse_factorials[i]%mod;
	int total=0;
	FOR_LOOP(i,1,m-n+1){
		add_mod(total,1ll*gPoly[n]*G(i+1,m-n-i+1)%mod*factorials[n]%mod*i%mod);
		gPoly=multiplyPolynomials(gPoly,polyF);gPoly.resize(n+1);
	}
	cout<<total;
	return 0;
}
